import{_ as s,c as i,o as a,ag as t}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Authentication and Authorization Mechanisms in Modern Web Apps","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/Communication_and_Security/What_authentication_authorization_mechanisms_do_you_use_on_your_project_Please_describe_how_they_work.md","filePath":"senior_growth/Communication_and_Security/What_authentication_authorization_mechanisms_do_you_use_on_your_project_Please_describe_how_they_work.md"}'),n={name:"senior_growth/Communication_and_Security/What_authentication_authorization_mechanisms_do_you_use_on_your_project_Please_describe_how_they_work.md"};function o(r,e,l,h,c,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="🔐-authentication-and-authorization-mechanisms-in-modern-web-apps" tabindex="-1">Authentication and Authorization Mechanisms in Modern Web Apps <a class="header-anchor" href="#🔐-authentication-and-authorization-mechanisms-in-modern-web-apps" aria-label="Permalink to “Authentication and Authorization Mechanisms in Modern Web Apps”">​</a></h1><p>In modern frontend-backend architectures, <strong>authentication</strong> and <strong>authorization</strong> are separate concerns:</p><ul><li><strong>Authentication:</strong> Verifying <strong>who the user is</strong>.</li><li><strong>Authorization:</strong> Determining <strong>what the user is allowed to do</strong>.</li></ul><p>Here’s a detailed overview of commonly used mechanisms and how they work.</p><hr><h2 id="_1️⃣-jwt-json-web-tokens" tabindex="-1"><span class="hub-section-number">1 </span>JWT (JSON Web Tokens) <a class="header-anchor" href="#_1️⃣-jwt-json-web-tokens" aria-label="Permalink to “1 JWT (JSON Web Tokens)”">​</a></h2><h3 id="🔑-what-it-is" tabindex="-1"><span class="hub-section-number">1.1 </span>What It Is <a class="header-anchor" href="#🔑-what-it-is" aria-label="Permalink to “1.1 What It Is”">​</a></h3><ul><li>JWT is a compact claims format. A signed token provides integrity under a verified key/algorithm; ordinary signed payloads are readable, and the format alone is not an authentication or authorization system.</li><li>Contains: <ul><li>Header (algorithm)</li><li>Payload (user info, roles)</li><li>Signature/MAC (for example HMAC, RSA or an appropriate elliptic-curve algorithm under a fixed verified policy)</li></ul></li></ul><p><strong>Example payload:</strong></p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;sub&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;12345&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Alice&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;exp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1719993600</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="🔧-how-it-works" tabindex="-1"><span class="hub-section-number">1.2 </span>How It Works <a class="header-anchor" href="#🔧-how-it-works" aria-label="Permalink to “1.2 How It Works”">​</a></h3><ol><li>User logs in → server verifies credentials.</li><li>Server generates JWT and sends it to client.</li><li>Choose a transport contract. A JavaScript-held access token can be attached as a Bearer header; a HttpOnly cookie is sent by browser cookie rules and cannot be read by JavaScript to construct that header.</li><li>For the JavaScript-held Bearer alternative only:</li></ol><div class="language-http"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;JWT&gt;</span></span></code></pre></div><ol start="5"><li>Server validates an allowlisted algorithm/key, issuer, audience, time/required application claims and intended token purpose; then separately authorizes this action/resource/tenant. Decoding is not verification.</li><li>Optionally, use <strong>refresh tokens</strong> to issue new JWTs when expired.</li></ol><h3 id="✅-pros" tabindex="-1"><span class="hub-section-number">1.3 </span>Pros <a class="header-anchor" href="#✅-pros" aria-label="Permalink to “1.3 Pros”">​</a></h3><ul><li>Local signature verification can avoid a session lookup, but revocation, rotation and current permissions may still need server state.</li><li>Scales well across distributed systems.</li><li>Can include roles/permissions in payload.</li></ul><h3 id="❌-cons" tabindex="-1"><span class="hub-section-number">1.4 </span>Cons <a class="header-anchor" href="#❌-cons" aria-label="Permalink to “1.4 Cons”">​</a></h3><ul><li>Long-lived tokens can be stolen if not stored securely.</li><li>Choose expiration, reauthentication and optional refresh/revocation policies. A refresh mechanism is not universally mandatory.</li></ul><hr><h2 id="_2️⃣-session-based-authentication" tabindex="-1"><span class="hub-section-number">2 </span>Session-Based Authentication <a class="header-anchor" href="#_2️⃣-session-based-authentication" aria-label="Permalink to “2 Session-Based Authentication”">​</a></h2><h3 id="🔑-what-it-is-1" tabindex="-1"><span class="hub-section-number">2.1 </span>What It Is <a class="header-anchor" href="#🔑-what-it-is-1" aria-label="Permalink to “2.1 What It Is”">​</a></h3><ul><li>Traditional approach using <strong>server-side sessions</strong>.</li><li>Server keeps a <strong>session store</strong> (memory, database, Redis) mapping session ID → user info.</li></ul><h3 id="🔧-how-it-works-1" tabindex="-1"><span class="hub-section-number">2.2 </span>How It Works <a class="header-anchor" href="#🔧-how-it-works-1" aria-label="Permalink to “2.2 How It Works”">​</a></h3><ol><li>User logs in → server creates session → stores session ID in server-side store.</li><li>Session ID is sent to client as a <strong>cookie</strong> (<code>HttpOnly</code>, <code>Secure</code>).</li><li>Browser sends an eligible cookie according to domain/path/Secure/SameSite, credentials mode and browser policy.</li><li>Server checks session ID → validates user and permissions.</li></ol><h3 id="✅-pros-1" tabindex="-1"><span class="hub-section-number">2.3 </span>Pros <a class="header-anchor" href="#✅-pros-1" aria-label="Permalink to “2.3 Pros”">​</a></h3><ul><li>Can support secure sessions with proper lifecycle, cookie scope, CSRF/XSS defenses and authorization; two cookie flags alone do not establish security.</li><li>Can easily revoke sessions server-side.</li><li>Works well with sensitive data.</li></ul><h3 id="❌-cons-1" tabindex="-1"><span class="hub-section-number">2.4 </span>Cons <a class="header-anchor" href="#❌-cons-1" aria-label="Permalink to “2.4 Cons”">​</a></h3><ul><li>Stateful → requires server session management.</li><li>Harder to scale across distributed servers (needs shared session store).</li></ul><hr><h2 id="_3️⃣-oauth-2-0" tabindex="-1"><span class="hub-section-number">3 </span>OAuth 2.0 <a class="header-anchor" href="#_3️⃣-oauth-2-0" aria-label="Permalink to “3 OAuth 2.0”">​</a></h2><h3 id="🔑-what-it-is-2" tabindex="-1"><span class="hub-section-number">3.1 </span>What It Is <a class="header-anchor" href="#🔑-what-it-is-2" aria-label="Permalink to “3.1 What It Is”">​</a></h3><ul><li><p>Standard <strong>authorization framework</strong> for delegating access.</p></li><li><p>OAuth delegates API access. For standardized user login use OpenID Connect (OIDC), an identity layer on OAuth2; do not treat an arbitrary access token as a login assertion.</p></li><li><p>Components:</p><ul><li><strong>Resource Owner:</strong> User</li><li><strong>Client:</strong> Your app</li><li><strong>Authorization Server:</strong> Issues access tokens</li><li><strong>Resource Server:</strong> Protects APIs</li></ul></li></ul><h3 id="🔧-how-it-works-2" tabindex="-1"><span class="hub-section-number">3.2 </span>How It Works <a class="header-anchor" href="#🔧-how-it-works-2" aria-label="Permalink to “3.2 How It Works”">​</a></h3><ol><li>User authorizes your app → app receives <strong>authorization code</strong>.</li><li>App exchanges code for <strong>access token</strong> (and optionally refresh token).</li><li>Client uses <strong>access token</strong> to access protected API.</li><li>Access tokens may be opaque or structured. The resource server follows the issuer&#39;s validation/introspection contract; the client must not assume every token is a JWT.</li></ol><h3 id="✅-pros-2" tabindex="-1"><span class="hub-section-number">3.3 </span>Pros <a class="header-anchor" href="#✅-pros-2" aria-label="Permalink to “3.3 Pros”">​</a></h3><ul><li>Standardized, widely supported.</li><li>OIDC adds standardized identity/login semantics that can support SSO.</li><li>Access tokens can be scoped and short-lived.</li></ul><h3 id="❌-cons-2" tabindex="-1"><span class="hub-section-number">3.4 </span>Cons <a class="header-anchor" href="#❌-cons-2" aria-label="Permalink to “3.4 Cons”">​</a></h3><ul><li>More complex to implement.</li><li>Requires secure storage of tokens and HTTPS.</li></ul><hr><h2 id="_4️⃣-role-based-access-control-rbac-permissions" tabindex="-1"><span class="hub-section-number">4 </span>Role-Based Access Control (RBAC) &amp; Permissions <a class="header-anchor" href="#_4️⃣-role-based-access-control-rbac-permissions" aria-label="Permalink to “4 Role-Based Access Control (RBAC) &amp; Permissions”">​</a></h2><h3 id="🔑-what-it-is-3" tabindex="-1"><span class="hub-section-number">4.1 </span>What It Is <a class="header-anchor" href="#🔑-what-it-is-3" aria-label="Permalink to “4.1 What It Is”">​</a></h3><ul><li>Authorization mechanism controlling <strong>what users can do</strong> based on <strong>roles</strong> or <strong>permissions</strong>.</li><li>Often combined with JWT or session-based auth.</li></ul><p><strong>Example:</strong></p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;sub&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;12345&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;permissions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;read_users&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edit_users&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;delete_users&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="🔧-how-it-works-3" tabindex="-1"><span class="hub-section-number">4.2 </span>How It Works <a class="header-anchor" href="#🔧-how-it-works-3" aria-label="Permalink to “4.2 How It Works”">​</a></h3><ol><li>Backend checks user role/permissions before allowing an action.</li><li>Frontend can <strong>conditionally render UI</strong> based on permissions.</li></ol><hr><h2 id="_5️⃣-practical-implementation-in-projects" tabindex="-1"><span class="hub-section-number">5 </span>Practical Implementation in Projects <a class="header-anchor" href="#_5️⃣-practical-implementation-in-projects" aria-label="Permalink to “5 Practical Implementation in Projects”">​</a></h2><ul><li><p><strong>Frontend:</strong></p><ul><li>Login form → sends credentials to API.</li><li>In a cookie-session design, use the eligible HttpOnly session cookie and CSRF protection; JavaScript does not read the cookie.</li><li>In the separate Bearer design, keep the short-lived token in memory and explicitly attach it to the intended API.</li><li>Implement reauthentication or optional controlled refresh according to the session policy; never blindly replay arbitrary writes.</li></ul></li><li><p><strong>Backend:</strong></p><ul><li>Validate the full JWT application contract or a current, unexpired, nonrevoked session record.</li><li>Check <strong>roles/permissions</strong> for protected endpoints.</li><li>Return 401 (unauthenticated) or 403 (unauthorized) if invalid.</li></ul></li><li><p><strong>Security Best Practices:</strong></p><ul><li>Always use <strong>HTTPS</strong></li><li><strong>HttpOnly + Secure cookies</strong> for sensitive tokens</li><li>Implement <strong>CSRF protection</strong> if using cookies</li><li>Keep access credentials suitably short-lived; if refresh is used, protect its rotation/reuse-detection/revocation lifecycle</li></ul></li></ul><hr><h3 id="🧠-summary" tabindex="-1"><span class="hub-section-number">5.1 </span>Summary <a class="header-anchor" href="#🧠-summary" aria-label="Permalink to “5.1 Summary”">​</a></h3><table tabindex="0"><thead><tr><th>Mechanism</th><th>Authentication</th><th>Authorization</th><th>Storage</th><th>Pros</th><th>Cons</th></tr></thead><tbody><tr><td>JWT</td><td>Claims format, not a login protocol</td><td>Claims inform separate server decisions</td><td>Depends on transport</td><td>Local verification possible</td><td>Validation, theft/revocation policy</td></tr><tr><td>Session</td><td>Yes</td><td>Yes</td><td>HttpOnly cookie</td><td>Secure, revocable</td><td>Stateful, scaling requires store</td></tr><tr><td>OAuth2 / OIDC</td><td>OAuth alone: no standardized identity; OIDC: yes</td><td>Delegated scopes plus API policy</td><td>Protocol/design dependent</td><td>Standard federation</td><td>Callback/token/session validation</td></tr><tr><td>RBAC/Permissions</td><td>No</td><td>Yes</td><td>Combined with JWT/session</td><td>Fine-grained access control</td><td>Needs server enforcement</td></tr></tbody></table><hr><blockquote><p>Choose session/transport/protocol from the application&#39;s trust boundaries, not from a slogan that JWT is always more scalable or sessions are only for sensitive apps. Roles in a signed token can become stale; enforce ownership/tenant checks on every protected server operation.</p></blockquote><h2 id="one-coherent-browser-flow-with-explicit-alternatives" tabindex="-1"><span class="hub-section-number">6 </span>One coherent browser flow, with explicit alternatives <a class="header-anchor" href="#one-coherent-browser-flow-with-explicit-alternatives" aria-label="Permalink to “6 One coherent browser flow, with explicit alternatives”">​</a></h2><p>For the same-origin learning app, a server-backed cookie session is a straightforward primary browser boundary. An OIDC login handled on the backend can keep provider access/refresh tokens out of JavaScript and establish a local opaque session. The dedicated Node authentication chapter&#39;s JWT API examples remain a separate valid API-token exercise; do not combine cookie storage with a client read-to-Bearer step.</p><p>For OIDC, use a maintained integration and authorization-code flow with PKCE as supported/required by the client profile. Bind the redirect to the initiating transaction using the library&#39;s state/nonce/PKCE checks; enforce registered redirect URLs. Validate ID-token signature, issuer, audience, expiration and applicable nonce before creating a session. Identify a provider account using issuer plus subject, not a mutable email alone. An ID token is for the client; an access token is for its resource server. A successful provider login does not assign application admin rights.</p><p>Rotate the local session identifier at authentication/privilege changes, enforce idle/absolute expiry and invalidate it server-side on logout. Cookie deletion alone does not invalidate a stolen session. Authorization dependencies failing should yield a controlled service failure, not a fabricated invalid-token verdict or fail-open access. Decide what logout means for local sessions, outstanding API tokens and the upstream provider; they are different lifecycles.</p><p>If refresh is required, implement the provider&#39;s current protected refresh policy (including rotation/reuse detection or sender constraints as appropriate) through a maintained library/service. Coordinate concurrent refreshes and bound retries. Never put client secrets in a browser bundle, log token values or silently replay an uncertain non-idempotent write after401. Reauthentication is a legitimate alternative for short sessions.</p><p><strong>Worked decision:</strong> the browser sends a cookie-authenticated PATCH to /api/profile with a session-bound CSRF token. The server resolves the session, validates provenance/CSRF/schema, derives the principal and allows only that user&#39;s editable profile fields. A role or userId submitted in the body cannot promote the caller or choose another owner. No provider token is required in the browser for this local operation. The adjacent token-storage note shows this transport as runnable JavaScript; the Node module contains the fuller server boundary.</p><p>Authoritative references checked2026-10-22: <a href="https://openid.net/specs/openid-connect-core-1_0.html" target="_blank" rel="noreferrer">OIDC Core1.0</a>, <a href="https://www.rfc-editor.org/rfc/rfc9700.html" target="_blank" rel="noreferrer">OAuth security BCP RFC9700</a>, <a href="https://www.rfc-editor.org/rfc/rfc8725.html" target="_blank" rel="noreferrer">JWT BCP RFC8725</a>, <a href="https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP session lifecycle</a>.</p><h2 id="separate-practice" tabindex="-1"><span class="hub-section-number">7 </span>Separate practice <a class="header-anchor" href="#separate-practice" aria-label="Permalink to “7 Separate practice”">​</a></h2><p>Use the <a href="./../../practice/engineering/security/What_authentication_authorization_mechanisms_do_you_use_on_your_project_Please_describe_how_they_work.html">focused acceptance and evidence requirements</a>. All learner practice remains outstanding.</p>`,63)])])}const k=s(n,[["render",o]]);export{u as __pageData,k as default};
